def find_max(numbers):
    if not numbers:
        return None
    max_val = numbers[0]
    for num in numbers:
        if num > max_val:
            max_val = num
    return max_val

def remove_duplicates(lst=None):
    if lst is None:
        lst = []
    return list(set(lst))

def safe_get(lst, index):
    if index < 0 or index >= len(lst):
        return None
    return lst[index]

