def reverse_string(s):
    if not isinstance(s, str):
        raise TypeError("Input must be a string")
    return s[::-1]


def capitalize_words(text):
    if not isinstance(text, str):
        raise TypeError("Input must be a string")
    words = text.split()
    result = []
    for word in words:
        result.append(word.capitalize())
    return ' '.join(result)


def count_vowels(text):
    if not isinstance(text, str):
        raise TypeError("Input must be a string")
    vowels = 'aeiouAEIOU'
    count = 0
    for char in text:
        if char in vowels:
            count += 1
    return count
